effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l = gmLum(c);
  vec3 cold = vec3(0.86, 1.00, 1.14);
  vec3 g = c * mix(vec3(1.0), cold, coolness);
  float sh = 1.0 - smoothstep(0.0, 0.5, l);
  g = mix(g, g * vec3(0.85, 0.98, 1.15), sh * shadowTint);
  g = clamp((g - 0.5) * contrast + 0.5, 0.0, 1.0);
  vec3 col = mix(c, g, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
